def solve():
    add = lambda x, y: x ^ y
    mul_table = [
        [0, 0, 0, 0],
        [0, 1, 2, 3],
        [0, 2, 3, 1],
        [0, 3, 1, 2]
    ]
    mul = lambda x, y: mul_table[x][y]

    points = [(x, y) for x in range(4) for y in range(4)]
    lines = []

    # x = c
    for c in range(4):
        line = []
        for p in points:
            if p[0] == c:
                line.append(p)
        lines.append(line)

    # y = mx + c
    for m in range(4):
        for c in range(4):
            line = []
            for p in points:
                if p[1] == add(mul(m, p[0]), c):
                    line.append(p)
            lines.append(line)

    blocks = []
    for line in lines:
        blocks.append([points.index(p) for p in line])

    # Repeat 3 times
    all_blocks = blocks * 3

    matrix = [[0]*60 for _ in range(16)]
    for j, block in enumerate(all_blocks):
        for i in block:
            matrix[i][j] = 1

    # Verify
    for i in range(16):
        assert sum(matrix[i]) == 15
    for j in range(60):
        assert sum(matrix[i][j] for i in range(16)) == 4
    for i1 in range(16):
        for i2 in range(i1+1, 16):
            assert sum(matrix[i1][j] * matrix[i2][j] for j in range(60)) == 3

    flat = [matrix[i][j] for i in range(16) for j in range(60)]
    print(flat)

solve()
